  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Cell Theory and Types of Cells$j$, $j${"readings": [{"title": "Psalm 139 (King James Version)", "url": "/portal/bible/Psalms/139"}], "body": "Every living thing is made of cells. The cell is the basic unit of structure and function in life. Psalm 139:14 says, I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well.\n\nCell theory has three parts:\nAll living things are made of one or more cells.\nThe cell is the basic unit of structure and function in organisms.\nAll cells come from existing cells.\n\nMany scientists built this theory over time. Robert Hooke named cells in 1665 when he looked at cork. Anton van Leeuwenhoek observed living microorganisms. Schleiden and Schwann concluded that plants and animals are made of cells, and Virchow stated that cells come from cells. Better microscopes led to better knowledge, which shows how science grows.\n\nProkaryotic cells have no nucleus. Their DNA floats in the cytoplasm. They are small and simple. Bacteria are prokaryotes.\nEukaryotic cells have a nucleus and other organelles enclosed by membranes. Plants, animals, fungi and protists are made of eukaryotic cells.\n\nCharacteristics of life: made of cells, use energy, respond to the environment, grow and develop, reproduce, maintain homeostasis (a steady internal condition) and adapt over generations.\n\nMicroscope math: total magnification equals ocular lens power times objective lens power. A 10 times ocular with a 40 times objective gives 400 times.\n\nYour task: (1) State the three parts of cell theory. (2) Tell two differences between prokaryotic and eukaryotic cells. (3) Find the total magnification of a 10 times ocular and a 100 times objective.\n\nFlorida standards: SC.912.L.14.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.14.1", "script": "Welcome to Unit 2. This is Dr. Jenkins. Listen, everything alive is made of cells, and Psalm one thirty nine and fourteen says, I am fearfully and wonderfully made: marvellous are thy works. Today we look at the building block of every living thing.\n\nNow watch this. Cell theory has three parts. First, all living things are made of one or more cells. Second, the cell is the basic unit of structure and function. Third, all cells come from existing cells. Many scientists built this theory. Robert Hooke named cells in sixteen sixty five when he looked at cork. Leeuwenhoek saw living microorganisms. Schleiden and Schwann concluded that plants and animals are made of cells, and Virchow said that cells come from cells. Better microscopes brought better knowledge, and that is how science grows.\n\nLook at this. Prokaryotic cells have no nucleus. Their DNA floats in the cytoplasm. They are small and simple, and bacteria are prokaryotes. Eukaryotic cells have a nucleus and other organelles wrapped in membranes. Plants, animals, fungi and protists are made of eukaryotic cells.\n\nWhat makes something alive? Living things are made of cells, use energy, respond to the environment, grow and develop, reproduce, maintain homeostasis, which means a steady internal condition, and adapt over generations.\n\nA quick skill. Total magnification equals the ocular lens power times the objective lens power. A ten times ocular with a forty times objective gives four hundred times.\n\nYour task today. State the three parts of cell theory. Tell two differences between prokaryotic and eukaryotic cells. And find the magnification for a ten times ocular with a one hundred times objective. Take the four question check when you finish.\n\nSmall things show great wisdom. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Cell Theory and Types of Cells$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Organelles and Their Jobs$j$, $j${"readings": [{"title": "1 Corinthians 12 (King James Version)", "url": "/portal/bible/1Corinthians/12"}], "body": "Eukaryotic cells contain organelles, small structures that each do a job. A cell works like a well run school or ministry, where every part has a role. First Corinthians 12:14 says, For the body is not one member, but many.\n\nNucleus: holds the DNA and directs the cell. The nucleolus makes ribosomes.\nRibosomes: build proteins. They float free or sit on the rough endoplasmic reticulum.\nRough ER: has ribosomes and makes and folds proteins. Smooth ER: makes lipids and helps remove toxins.\nGolgi apparatus: sorts, packages and ships proteins, like a post office.\nMitochondria: release usable energy (ATP) from food by cellular respiration, the powerhouse.\nLysosomes: contain enzymes that break down wastes and worn parts.\nVacuoles: store water, food and wastes; a plant has one large central vacuole.\nChloroplasts (plants and algae): carry out photosynthesis using the green pigment chlorophyll.\nCell wall (plants, fungi, many protists): rigid outer support made of cellulose in plants.\nCell membrane: the flexible boundary of every cell.\nCytoskeleton: protein fibers that give shape and move parts.\n\nPlant cells have a cell wall, chloroplasts and a large central vacuole. Animal cells do not, but they have lysosomes and often centrioles.\n\nThe mitochondrion and chloroplast have their own DNA, so scientists propose they came from small cells living inside larger ones. This is called the endosymbiotic theory.\n\nYour task: (1) Trace a protein from nucleus to cell exit using organelle names. (2) Tell three structures found in plant cells but not animal cells. (3) Explain why muscle cells have many mitochondria.\n\nFlorida standards: SC.912.L.14.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.14.3", "script": "Welcome back. Dr. Jenkins here. Listen, a cell works like a well run ministry, and First Corinthians twelve and fourteen says, For the body is not one member, but many. Every organelle has a job.\n\nNow watch this. The nucleus holds the DNA and directs the cell. Ribosomes build proteins. Some float free and some sit on the rough endoplasmic reticulum, which makes and folds proteins. The smooth ER makes lipids and helps remove toxins. The Golgi apparatus sorts, packages and ships proteins, like a post office. Mitochondria release usable energy called ATP from food, so we call them the powerhouse. Lysosomes break down wastes and worn parts. Vacuoles store water, food and wastes.\n\nLook at the differences. Plant cells have a rigid cell wall made of cellulose, chloroplasts that carry out photosynthesis with chlorophyll, and a large central vacuole. Animal cells do not have those, but they have lysosomes and often centrioles. Every cell has a flexible cell membrane and a cytoskeleton of protein fibers that gives shape and moves parts.\n\nHere is a fascinating point. Mitochondria and chloroplasts have their own DNA, so scientists propose they began as small cells living inside larger cells. That idea is called the endosymbiotic theory.\n\nYour task today. Trace a protein from the nucleus to the cell exit using organelle names. Tell three structures found in plant cells but not animal cells. And explain why muscle cells have many mitochondria. Take the four question check when you finish.\n\nEach part matters in the body of Christ and in the body of a cell. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Organelles and Their Jobs$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 The Cell Membrane and Transport$j$, $j${"readings": [{"title": "Psalm 100 (King James Version)", "url": "/portal/bible/Psalms/100"}], "body": "The cell membrane controls what enters and leaves the cell. It is selectively permeable, meaning it lets some substances pass and blocks others. Proverbs 4:23 says, Keep thy heart with all diligence; for out of it are the issues of life. A cell guards its boundary with care.\n\nStructure: a phospholipid bilayer. Each phospholipid has a head that likes water (hydrophilic) and two tails that avoid water (hydrophobic). The tails face inward, forming a barrier. Proteins float in the bilayer and act as channels, pumps and receptors. This is called the fluid mosaic model. Cholesterol helps keep the membrane stable.\n\nPassive transport needs no cell energy. Substances move from high concentration to low concentration, down the concentration gradient.\nDiffusion: movement of particles from high to low concentration, such as oxygen entering a cell.\nFacilitated diffusion: diffusion through a protein channel, such as glucose.\nOsmosis: diffusion of water through a membrane.\n\nActive transport uses ATP to move substances from low to high concentration, against the gradient, with protein pumps. Endocytosis brings large particles in by a pocket of membrane, and exocytosis sends them out.\n\nOsmosis and solutions: In an isotonic solution, water moves in and out equally. In a hypotonic solution (less solute outside), water moves into the cell and it may swell or burst. In a hypertonic solution (more solute outside), water leaves the cell and it shrivels. A plant cell wall prevents bursting, and a plant wilts when water leaves.\n\nYour task: (1) Explain why the membrane is called selectively permeable. (2) Predict what happens to a red blood cell placed in pure water. (3) Compare diffusion and active transport.\n\nFlorida standards: SC.912.L.14.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.14.3", "script": "Welcome back. Dr. Jenkins here. Listen, every cell guards its boundary. Proverbs four and twenty three says, Keep thy heart with all diligence; for out of it are the issues of life. The cell membrane is the guard of the cell.\n\nNow watch this. The membrane is selectively permeable, meaning it lets some things pass and blocks others. It is a phospholipid bilayer. Each phospholipid has a head that loves water and two tails that avoid water. The tails face inward and make a barrier. Proteins float in the bilayer as channels, pumps and receptors. We call this the fluid mosaic model.\n\nLook at passive transport. It needs no cell energy. Particles move from high concentration to low concentration, down the gradient. Diffusion is that movement, like oxygen entering a cell. Facilitated diffusion uses a protein channel, like glucose. Osmosis is the diffusion of water through a membrane.\n\nActive transport is different. It uses ATP to move substances from low to high concentration, against the gradient, with protein pumps. Endocytosis brings large particles in with a pocket of membrane, and exocytosis sends them out.\n\nNow osmosis and solutions. In an isotonic solution, water moves in and out equally. In a hypotonic solution there is less solute outside, so water rushes in and the cell may swell or burst. In a hypertonic solution there is more solute outside, so water leaves and the cell shrivels. A plant cell wall keeps the cell from bursting, and a plant wilts when water leaves.\n\nYour task today. Explain why the membrane is selectively permeable. Predict what happens to a red blood cell in pure water. And compare diffusion with active transport. Take the four question check when you finish.\n\nGuard your heart with diligence. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 The Cell Membrane and Transport$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 The Cell Cycle and Mitosis$j$, $j${"readings": [{"title": "Ecclesiastes 3 (King James Version)", "url": "/portal/bible/Ecclesiastes/3"}], "body": "Cells grow and divide. A body grows, heals and replaces cells through the cell cycle. Ecclesiastes 3:1 says, To every thing there is a season, and a time to every purpose under the heaven.\n\nWhy cells divide: As a cell grows, its volume increases faster than its surface area, so it cannot move materials in and out well enough. Cells divide to stay small enough to work well, to grow, and to repair damage.\n\nThe cell cycle:\nInterphase (most of the cycle): G1, the cell grows. S, the DNA is copied (replicated). G2, the cell prepares to divide.\nMitosis: the nucleus divides.\nCytokinesis: the cytoplasm divides into two cells.\n\nStages of mitosis:\nProphase: chromosomes condense and become visible; the nuclear envelope breaks down; spindle fibers form.\nMetaphase: chromosomes line up in the middle.\nAnaphase: sister chromatids separate and move to opposite ends.\nTelophase: nuclear envelopes re form; chromosomes loosen.\nCytokinesis then forms two identical daughter cells. In animal cells the membrane pinches in; in plants a cell plate forms.\n\nMitosis gives two cells with the same number of chromosomes and identical DNA as the parent. Humans have 46 chromosomes in body cells.\n\nControl and cancer: checkpoints stop the cycle if something is wrong. Cancer is uncontrolled cell division caused when the controls fail.\n\nYour task: (1) Put the stages of mitosis in order. (2) Tell what happens during S phase. (3) If a human skin cell divides by mitosis, how many chromosomes are in each daughter cell?\n\nFlorida standards: SC.912.L.16.17.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.16.17", "script": "Welcome back. Dr. Jenkins here. Listen, Ecclesiastes three and one says, To every thing there is a season, and a time to every purpose under the heaven. Cells have seasons too, and today we study the cell cycle.\n\nWhy do cells divide? As a cell grows, its volume increases faster than its surface area, so it cannot move materials in and out well enough. Cells divide to stay small enough to work, to help the body grow, and to repair damage.\n\nNow watch this. The cell cycle has interphase, mitosis and cytokinesis. Interphase is most of the cycle. In G one the cell grows. In S phase the DNA is copied. In G two the cell prepares to divide. Then mitosis, where the nucleus divides, and cytokinesis, where the cytoplasm divides.\n\nLook at the stages. In prophase the chromosomes condense, the nuclear envelope breaks down, and spindle fibers form. In metaphase the chromosomes line up in the middle. In anaphase the sister chromatids separate and move to opposite ends. In telophase the nuclear envelopes re form and the chromosomes loosen. Then cytokinesis makes two identical daughter cells. In animal cells the membrane pinches in, and in plant cells a cell plate forms. You can remember the order with the letters P, M, A, T.\n\nMitosis gives two cells with the same number of chromosomes and identical DNA as the parent. A human body cell has forty six chromosomes.\n\nThere are checkpoints that stop the cycle if something is wrong. Cancer is uncontrolled cell division, which happens when those controls fail.\n\nYour task today. Put the stages of mitosis in order. Tell what happens in S phase. And find the chromosome number of each daughter cell from a human skin cell. Take the four question check when you finish.\n\nThere is a time for everything, including growth. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 The Cell Cycle and Mitosis$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Cell Analogy and Transport Investigation$j$, $j${"prompt": "Part 1: Cell City Analogy. Compare a eukaryotic cell to a ministry, school or city of your choice. Match at least eight organelles to a part of your analogy and tell the job of each. Include the nucleus, mitochondria, ribosomes, Golgi apparatus, cell membrane and one more. First Corinthians 12:14 says, For the body is not one member, but many.\n\nPart 2: Transport. Describe a safe investigation (for example, a potato slice or an egg placed in salt water, sugar water and pure water). Tell your hypothesis, what you will measure, and what you expect in hypotonic, isotonic and hypertonic solutions. Use the words osmosis and selectively permeable.\n\nPart 3: Microscope math. Find the total magnification for a 10 times ocular and a 40 times objective, and for a 10 times ocular and a 100 times objective.\n\nPart 4: Mitosis. Draw or describe the four stages of mitosis in order and explain why mitosis keeps the chromosome number the same.\n\nPart 5: Reflection. In at least 60 words, explain how the way cells divide, guard their boundary and share work can teach us about unity and diligence.", "rubric": "70 points. Analogy with eight organelles: 20 points. Transport investigation: 16 points. Microscope math: 8 points. Mitosis: 16 points. Reflection: 6 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Cell Analogy and Transport Investigation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Fearfully and Wonderfully Made$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains in your own words why scientists say every living thing is made of cells, (2) describes one organelle and tells what would happen to a cell if it stopped working, (3) tells how the many parts of a cell working together is like people working together in a church or school, and (4) connects your answer to Psalm 139:14, which says, I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well. Then write a respectful reply of at least 40 words to another student, or answer this question: Why can a cell not grow without limit? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Fearfully and Wonderfully Made$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Cell Theory and Types of Cells$j$, $j${"questions": [{"q": "Which statement is part of cell theory?", "options": ["All cells come from existing cells", "Cells have no function", "Only animals have cells", "Cells appear from nonliving matter every day"]}, {"q": "A prokaryotic cell differs from a eukaryotic cell because it has:", "options": ["Mitochondria", "A nucleus", "A large vacuole", "No nucleus"]}, {"q": "Total magnification of a 10 times ocular and a 40 times objective is:", "options": ["40 times", "4000 times", "400 times", "50 times"]}, {"q": "Keeping a steady internal condition is called:", "options": ["Mitosis", "Homeostasis", "Evolution", "Diffusion"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Cell Theory and Types of Cells$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,2,1}'::int[], array[$j$The third part of cell theory says all cells come from existing cells.$j$,$j$Prokaryotes have no membrane bound nucleus.$j$,$j$10 times 40 equals 400.$j$,$j$Homeostasis is the maintenance of stable internal conditions.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Cell Theory and Types of Cells$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Organelles and Their Jobs$j$, $j${"questions": [{"q": "Which organelle releases usable energy (ATP) from food?", "options": ["Golgi apparatus", "Mitochondrion", "Ribosome", "Lysosome"]}, {"q": "Ribosomes are the site where cells build:", "options": ["Water", "Lipids only", "Proteins", "Starch only"]}, {"q": "Which structure is found in plant cells but NOT in animal cells?", "options": ["Cell membrane", "Chloroplast", "Nucleus", "Mitochondrion"]}, {"q": "The Golgi apparatus mainly:", "options": ["Makes ATP", "Sorts, packages and ships proteins", "Digests the whole cell", "Stores DNA"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Organelles and Their Jobs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,1}'::int[], array[$j$Mitochondria carry out cellular respiration to make ATP.$j$,$j$Ribosomes assemble amino acids into proteins.$j$,$j$Chloroplasts and cell walls are found in plants but not in animals.$j$,$j$The Golgi works like a post office for cell products.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Organelles and Their Jobs$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: The Cell Membrane and Transport$j$, $j${"questions": [{"q": "Which process uses cell energy to move substances against a concentration gradient?", "options": ["Osmosis", "Facilitated diffusion", "Active transport", "Diffusion"]}, {"q": "Osmosis is the diffusion of:", "options": ["Proteins across a membrane", "Oxygen only", "Salt only", "Water across a membrane"]}, {"q": "An animal cell placed in a hypotonic solution will:", "options": ["Lose water and shrivel", "Turn into a plant cell", "Take in water and swell", "Stay exactly the same"]}, {"q": "The cell membrane is made mainly of a:", "options": ["Phospholipid bilayer with proteins", "Single layer of starch", "Layer of DNA", "Layer of cellulose"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Cell Membrane and Transport$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,0}'::int[], array[$j$Active transport uses ATP and moves substances from low to high concentration.$j$,$j$Osmosis is the movement of water through a selectively permeable membrane.$j$,$j$A hypotonic solution has less solute outside, so water enters the cell.$j$,$j$The fluid mosaic model describes a phospholipid bilayer with embedded proteins.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Cell Membrane and Transport$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: The Cell Cycle and Mitosis$j$, $j${"questions": [{"q": "During which stage do chromosomes line up in the middle of the cell?", "options": ["Anaphase", "Telophase", "Metaphase", "Prophase"]}, {"q": "DNA is copied during the:", "options": ["Telophase", "S phase of interphase", "Anaphase", "Cytokinesis"]}, {"q": "Mitosis of a human body cell produces:", "options": ["Four cells with 23 chromosomes each", "Two cells with 23 chromosomes each", "One cell with 92 chromosomes", "Two identical cells with 46 chromosomes each"]}, {"q": "Uncontrolled cell division is called:", "options": ["Osmosis", "Cancer", "Homeostasis", "Photosynthesis"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: The Cell Cycle and Mitosis$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,1}'::int[], array[$j$In metaphase the chromosomes align at the cell's center.$j$,$j$The S phase is where DNA replication occurs.$j$,$j$Mitosis makes identical daughter cells with the same chromosome number.$j$,$j$Cancer results when the controls of the cell cycle fail.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: The Cell Cycle and Mitosis$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: The Cell, the Unit of Life$j$, $j${"questions": [{"q": "Which scientist stated that all cells come from existing cells?", "options": ["Hooke", "Leeuwenhoek", "Darwin", "Virchow"]}, {"q": "The organelle that holds the cell's DNA in a eukaryote is the:", "options": ["Lysosome", "Vacuole", "Ribosome", "Nucleus"]}, {"q": "Photosynthesis takes place in the:", "options": ["Chloroplast", "Mitochondrion", "Nucleus", "Golgi apparatus"]}, {"q": "A student sees a cell with a cell wall, a large central vacuole and chloroplasts. It is a:", "options": ["Bacterial cell", "Red blood cell", "Plant cell", "Animal cell"]}, {"q": "Movement of particles from high to low concentration without using energy is:", "options": ["Mitosis", "Active transport", "Diffusion", "Exocytosis"]}, {"q": "A cell in a hypertonic solution will:", "options": ["Stay the same", "Gain water and burst", "Divide", "Lose water and shrink"]}, {"q": "The correct order of mitosis is:", "options": ["Anaphase, prophase, metaphase, telophase", "Metaphase, prophase, telophase, anaphase", "Prophase, metaphase, anaphase, telophase", "Telophase, anaphase, metaphase, prophase"]}, {"q": "Why must cells divide rather than grow without limit?", "options": ["They would turn into water", "Surface area does not keep up with volume", "They would stop being alive for no reason", "They run out of DNA"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Cell, the Unit of Life$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,0,2,2,3,2,1}'::int[], array[$j$Rudolf Virchow concluded that cells come from cells.$j$,$j$The nucleus contains the DNA.$j$,$j$Chloroplasts contain chlorophyll and carry out photosynthesis.$j$,$j$Those three structures are found in plant cells.$j$,$j$Diffusion is a passive process.$j$,$j$More solute outside pulls water out of the cell.$j$,$j$Remember the order P, M, A, T.$j$,$j$A large cell cannot move materials in and out fast enough.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Cell, the Unit of Life$j$ on conflict (item_id) do nothing;
